using System;
using System.IO;

public class FileDeleter
{
    /// <summary>
    /// Permanently deletes files from a computer's hard drive.
    /// </summary>
    /// <param name="filePath">The path to the file to be deleted.</param>
    public static void DeleteFile(string filePath)
    {
        // Check if the file exists
        if (!File.Exists(filePath))
        {
            Console.WriteLine("The file does not exist.");
            return;
        }

        // Check if the file is a directory
        if (Directory.Exists(filePath))
        {
            Console.WriteLine("The path is a directory. Please provide a file path.");
            return;
        }

        // Try to delete the file
        try
        {
            // Use File.Delete to permanently delete the file
            File.Delete(filePath);
            Console.WriteLine("The file has been deleted.");
        }
        catch (UnauthorizedAccessException ex)
        {
            Console.WriteLine("You do not have permission to delete the file.");
        }
        catch (Exception ex)
        {
            Console.WriteLine("An error occurred: " + ex.Message);
        }
    }

    public static void Main(string[] args)
    {
        // Example usage
        string filePath = @"C:\path\to\file.txt";
        DeleteFile(filePath);
    }
}
